export interface Page<T>{readonly items:readonly T[];readonly nextCursor:string|null}
export type Authority='NATIVE'|'EXTERNAL';
export interface Membership{readonly id:string;readonly authority:Authority;readonly status:string;readonly version:number;readonly role:string;readonly leftAt:string|null}
