export interface NativeExecution{readonly authority:'NATIVE';readonly executionId:string;readonly taskId:string;readonly agentId:string;readonly status:string;readonly version:number;readonly startedAt:string|null;readonly finishedAt:string|null}
export interface Delegation{readonly id:string;readonly activityId:string;readonly collaborationId:string;readonly delegationId:string;readonly type:'DELEGATION';readonly sourceAgentId:string;readonly targetAgentId:string;readonly parentTaskId:string;readonly childTaskId:string|null;readonly sourceExecutionId:string|null;readonly status:string;readonly version:number;readonly createdAt:string;readonly updatedAt:string;readonly finishedAt:string|null;readonly execution:NativeExecution|null;readonly progress:null}
