export interface ExternalObservation{readonly activityId:string;readonly type:'EXTERNAL_OBSERVATION';readonly mappingId:string;readonly collaborationId:string|null;readonly delegationId:string|null;readonly agentId:string|null;readonly version:number;readonly execution:ExternalReference;readonly sourceOccurredAt:string|null;readonly observedAt:string|null;readonly updatedAt:string;readonly freshness:'RECENT_OBSERVATION'|'STALE'|'RETIRED'|'UNKNOWN';readonly connectionHealth:'UNKNOWN';readonly progress:null;readonly resultAvailability:'NOT_PROJECTED';readonly operations:readonly []}
