export interface Snapshot{readonly schemaVersion:2;readonly observedAt:string;readonly collaboration:Summary;readonly participants:Page<Participant>;readonly delegations:Page<Delegation>;readonly external:Page<ExternalObservation>;readonly synchronization:{readonly transport:'REST_POLL';readonly nativeAfterPosition:string;readonly externalSnapshotRequired:true};readonly progress:null}
