export interface State{readonly connected:boolean;readonly agentId:string|null;readonly agent:AgentView|null;readonly snapshot:Snapshot|null;readonly timeline:Timeline|null;readonly selectedId:string|null;readonly loading:boolean;readonly message:string;readonly stale:boolean;readonly historyOpen:boolean;readonly page:number}
